/**
 * genres.mjs — music generated by code, one function per genre.
 * Style packs pick a genre in style.json → "music": { "genre": "...", "bpm": N }.
 *
 *   ragtime     stride piano + syncopated melody + brushed backbeat     (Rubber Hose 1930)
 *   cooljazz    walking upright bass, vibraphone comping, brushes        (UPA 1950s)
 *   waltz       3/4 music-box melody over soft strings-like pad          (Silhouette 1920s fairy tale)
 *   pentatonic  plucked zither + breathy flute, lots of space            (Ink-wash 1960)
 *   lofi        mellow 7ths, soft kick + hat                             (cozy / modern)
 *   + recipe genres (data, see RECIPES): polka, funk, citypop, epic, sitcom, chiptune, eerie,
 *     occult, nihonga, ukiyoe, feature, cgi, winter, folk, adventure, sparkle, zany, saturday
 *
 * Add a genre: write compose<Name>(tr, ctx) and register it in GENRES. Keep it original:
 * progressions and scales are fine, never a known melody.
 */
import { SR, Track, rng } from "./instruments.mjs";

const PROG = {
  ragtime: [[0, 4, 7, 12], [9, 13, 16, 19], [2, 6, 9, 12], [7, 11, 14, 17]], // C A7 D7 G7
  lofi: [[5, 9, 12, 16], [4, 7, 11, 14], [2, 5, 9, 12], [0, 4, 7, 11]],     // Fmaj7 Em7 Dm7 Cmaj7
  cool: [[2, 5, 9, 12], [7, 11, 14, 17], [0, 4, 7, 11], [9, 12, 16, 19]],    // Dm7 G7 Cmaj7 Am7 (ii-V-I-vi)
  waltz: [[0, 4, 7], [9, 12, 16], [5, 9, 12], [7, 11, 14]],                  // C Am F G
};
const PENTA = [0, 2, 4, 7, 9]; // major pentatonic

function ragtime(tr, { beat, bars, r, key }) {
  for (let b = 0; b < bars; b++) {
    const chord = PROG.ragtime[b % 4].map((n) => n + 60 + key);
    const t0 = b * 4 * beat;
    tr.bass(t0, chord[0] - 24, beat * 0.9);
    tr.bass(t0 + 2 * beat, chord[2] - 24, beat * 0.9);
    for (const k of [1, 3]) {
      tr.piano(t0 + k * beat, chord[0] - 12, beat * 0.4, 0.07);
      chord.slice(1, 3).forEach((n) => tr.piano(t0 + k * beat, n - 12, beat * 0.4, 0.07));
      tr.noise(t0 + k * beat, 0.12, 0.12, b * 4 + k);
    }
    if (r() < 0.5) tr.noise(t0 + 3.5 * beat, 0.05, 0.12, b * 4 + 5, 900);
    let last = chord[2] + 12;
    for (let e = 0; e < 8; e++) {
      if (r() > (e === 3 || e === 5 ? 0.85 : 0.6)) continue;
      const pool = [...chord.map((n) => n + 12), chord[0] + 14, chord[0] + 21];
      const n = r() < 0.6 ? pool.reduce((a, c) => (Math.abs(c - last) < Math.abs(a - last) ? c : a)) : pool[Math.floor(r() * pool.length)];
      tr.piano(t0 + e * beat * 0.5, n, beat * 0.45, 0.16);
      last = n;
    }
  }
  return [0, 4, 7, 12];
}

function lofi(tr, { beat, bars, r, key }) {
  for (let b = 0; b < bars; b++) {
    const chord = PROG.lofi[b % 4].map((n) => n + 60 + key);
    const t0 = b * 4 * beat;
    chord.forEach((n, i) => tr.piano(t0 + i * 0.03, n - 12, beat * 3.6, 0.09, 0.002));
    tr.bass(t0, chord[0] - 24, beat * 2, 0.3);
    tr.bass(t0 + beat * 2.5, chord[2] - 24, beat * 1.4, 0.22);
    for (let k = 0; k < 4; k++) {
      if (k % 2 === 0) tr.kick(t0 + k * beat, 0.35);
      tr.noise(t0 + (k + 0.5) * beat, 0.05, 0.05, b * 9 + k);
    }
    for (let k = 0; k < 3; k++) if (r() < 0.6) tr.piano(t0 + (k * 1.25 + 0.5) * beat, chord[1 + Math.floor(r() * 3)] + 12, beat, 0.08, 0.001);
  }
  return [5, 9, 12, 16];
}

function cooljazz(tr, { beat, bars, r, key }) {
  const swing = (e) => (e % 2 === 0 ? 0 : beat * 0.16); // swung eighths
  for (let b = 0; b < bars; b++) {
    const chord = PROG.cool[b % 4].map((n) => n + 57 + key);
    const next = PROG.cool[(b + 1) % 4][0] + 57 + key;
    const t0 = b * 4 * beat;
    // walking bass: root, chord tone, chord tone, chromatic approach to next root
    const walk = [chord[0], chord[1 + Math.floor(r() * 2)], chord[2], next + (r() < 0.5 ? -1 : 1)];
    walk.forEach((n, k) => tr.upright(t0 + k * beat, n - 24, beat * 0.95, 0.42));
    // vibraphone comping: short chords on "2-and" and "4"
    for (const at of [1.5, 3]) chord.slice(1).forEach((n) => tr.vibes(t0 + at * beat + swing(1), n, beat * 0.5, 0.06));
    // brushes: swish on every beat, tap on 2 and 4
    for (let k = 0; k < 4; k++) {
      tr.swish(t0 + k * beat, beat * 0.9, 0.035, b * 8 + k);
      if (k % 2) tr.noise(t0 + k * beat, 0.08, 0.08, b * 8 + k + 50);
    }
    // a sparse vibes melody
    for (let e = 0; e < 8; e++) {
      if (r() > 0.32) continue;
      const n = chord[Math.floor(r() * 4)] + 12 + (r() < 0.3 ? 2 : 0);
      tr.vibes(t0 + e * beat * 0.5 + swing(e), n, beat * 0.6, 0.14);
    }
  }
  return [0, 4, 7, 11].map((n) => n - 3);
}

function waltz(tr, { beat, bars, r, key }) {
  // 3/4: one bar = 3 beats
  for (let b = 0; b < bars; b++) {
    const chord = PROG.waltz[b % 4].map((n) => n + 60 + key);
    const t0 = b * 3 * beat;
    tr.bass(t0, chord[0] - 24, beat * 1.2, 0.25);
    for (const k of [1, 2]) chord.forEach((n) => tr.flute(t0 + k * beat, n - 12, beat * 0.7, 0.025, b * 3 + k));
    // music-box melody: mostly chord tones, a passing step
    for (let k = 0; k < 3; k++) {
      if (k > 0 && r() < 0.35) continue;
      const n = chord[Math.floor(r() * 3)] + 12 + (r() < 0.25 ? 2 : 0);
      tr.bell(t0 + k * beat, n, k === 0 ? 0.22 : 0.15);
      if (r() < 0.3) tr.bell(t0 + (k + 0.5) * beat, n + (r() < 0.5 ? 2 : -1), 0.1);
    }
  }
  return [0, 4, 7, 12];
}

function pentatonic(tr, { beat, bars, r, key }) {
  const scale = (deg) => 62 + key + PENTA[((deg % 5) + 5) % 5] + 12 * Math.floor(deg / 5);
  let deg = 5;
  for (let b = 0; b < bars; b++) {
    const t0 = b * 4 * beat;
    tr.flute(t0, scale(0) - 12, beat * 3.8, 0.05, b + 1); // drone
    // zither phrase with space: 2–4 notes per bar, glissando-like runs sometimes
    const notes = 2 + Math.floor(r() * 3);
    for (let k = 0; k < notes; k++) {
      deg = Math.max(2, Math.min(11, deg + Math.floor(r() * 5) - 2));
      tr.pluck(t0 + (k * 4 * beat) / notes + (r() - 0.5) * 0.05, scale(deg), 0.32, b * 7 + k);
    }
    if (r() < 0.4) for (let g = 0; g < 4; g++) tr.pluck(t0 + 3 * beat + g * 0.06, scale(deg + g), 0.12, b * 7 + 20 + g);
    if (b % 2 === 1) tr.flute(t0 + beat, scale(deg + 5), beat * 2.5, 0.07, b + 40);
  }
  return [0, 4, 7];
}

/* ------------------------------------------------------------------------------------------
 * Data-driven genres: one engine, a recipe per genre. Recipe fields:
 *   meter       beats per bar (default 4)
 *   prog        list of chords as semitone offsets from the key root (C4 = 60)
 *   scale       lead scale degrees (semitones within an octave)
 *   bass        { inst, beats: [beat…], octave, walk }
 *   chords      { inst, beats, len, vel, octave }
 *   lead        { inst, density 0..1, octave, len, vel, steps (per bar) }
 *   drums       { kick: [beats], snare: [beats], hat: "8"|"16"|null, taiko: [beats], brush: bool }
 * ---------------------------------------------------------------------------------------- */
const SCALES = {
  major: [0, 2, 4, 5, 7, 9, 11], minor: [0, 2, 3, 5, 7, 8, 10], dorian: [0, 2, 3, 5, 7, 9, 10],
  penta: [0, 2, 4, 7, 9], minorPenta: [0, 3, 5, 7, 10], miyako: [0, 1, 5, 7, 8], harmMinor: [0, 2, 3, 5, 7, 8, 11],
};
const CH = {
  pop: [[0, 4, 7], [7, 11, 14], [9, 12, 16], [5, 9, 12]],               // I V vi IV
  minorEpic: [[0, 3, 7], [8, 12, 15], [3, 7, 10], [10, 14, 17]],        // i VI III VII
  minorDark: [[0, 3, 7], [5, 8, 12], [8, 12, 15], [7, 11, 14]],          // i iv VI V
  citypop: [[5, 9, 12, 16], [4, 7, 11, 14], [2, 5, 9, 12], [7, 11, 14, 17]],
  folk: [[0, 4, 7], [5, 9, 12], [7, 11, 14], [0, 4, 7]],                 // I IV V I
  folkMinor: [[0, 3, 7], [5, 8, 12], [7, 11, 14], [0, 3, 7]],            // i iv V i
  sitcom: [[0, 4, 7, 10], [5, 9, 12, 15], [0, 4, 7, 10], [7, 11, 14, 17]], // I7 IV7 I7 V7 (blues)
  feature: [[0, 4, 7], [9, 12, 16], [5, 9, 12], [7, 11, 14]],             // I vi IV V
  japan: [[0, 1, 5], [5, 7, 12], [0, 5, 7], [8, 12, 13]],
};

const RECIPES = {
  polka: { prog: CH.folk, scale: SCALES.major, bass: { inst: "bass", beats: [0, 2], octave: -24 }, chords: { inst: "reed", beats: [1, 3], len: 0.35, vel: 0.06 }, lead: { inst: "pluck", density: 0.7, octave: 12, steps: 8 }, drums: { kick: [0, 2], snare: [1, 3] } },
  funk: { prog: CH.minorDark, scale: SCALES.dorian, bass: { inst: "upright", beats: [0, 0.75, 1.5, 2, 2.75, 3.5], octave: -24 }, chords: { inst: "saw", beats: [1.5, 3.5], len: 0.15, vel: 0.07 }, lead: { inst: "saw", density: 0.35, octave: 12, steps: 8, vel: 0.08 }, drums: { kick: [0, 1.75, 2.5], snare: [1, 3], hat: "16" } },
  citypop: { prog: CH.citypop, scale: SCALES.major, bass: { inst: "upright", beats: [0, 1.5, 2, 3.5], octave: -24 }, chords: { inst: "epiano", beats: [0, 1.5, 2.5], len: 0.9, vel: 0.07 }, lead: { inst: "square", density: 0.45, octave: 12, steps: 8, vel: 0.05, duty: 0.25 }, drums: { kick: [0, 2], snare: [1, 3], hat: "8" } },
  epic: { prog: CH.minorEpic, scale: SCALES.harmMinor, bass: { inst: "bass", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], octave: -24 }, chords: { inst: "pad", beats: [0], len: 3.8, vel: 0.07 }, lead: { inst: "saw", density: 0.3, octave: 0, steps: 4, vel: 0.07, len: 0.9 }, drums: { taiko: [0, 0.75, 2, 2.5, 3.5], snare: [1, 3] } },
  sitcom: { prog: CH.sitcom, scale: SCALES.minorPenta, bass: { inst: "upright", beats: [0, 1, 2, 3], octave: -24, walk: true }, chords: { inst: "saw", beats: [1.5, 3.5], len: 0.18, vel: 0.06 }, lead: { inst: "saw", density: 0.4, octave: 12, steps: 8, vel: 0.06 }, drums: { kick: [0, 2], snare: [1, 3], hat: "8" }, swing: 0.16 },
  chiptune: { prog: CH.pop, scale: SCALES.major, bass: { inst: "tri", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], octave: -24 }, chords: { inst: "square", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], len: 0.12, vel: 0.025, arp: true, duty: 0.125 }, lead: { inst: "square", density: 0.8, octave: 12, steps: 8, vel: 0.06, duty: 0.5 }, drums: { kick: [0, 2], snare: [1, 3], hat: "8", noise: true } },
  eerie: { prog: CH.japan, scale: SCALES.miyako, bass: { inst: "bass", beats: [0], octave: -24 }, chords: { inst: "pad", beats: [0], len: 3.8, vel: 0.05 }, lead: { inst: "pluck", density: 0.4, octave: 12, steps: 8 }, drums: { taiko: [0] } },
  occult: { prog: CH.minorDark, scale: SCALES.minor, bass: { inst: "saw", beats: [0, 0.75, 2, 2.75], octave: -24, vel: 0.1 }, chords: { inst: "pad", beats: [0], len: 3.8, vel: 0.06 }, lead: { inst: "epiano", density: 0.3, octave: 12, steps: 8 }, drums: { kick: [0, 1.5, 2.75], snare: [2], hat: "16" } },
  nihonga: { prog: CH.japan, scale: SCALES.miyako, bass: { inst: "bass", beats: [0, 2], octave: -24 }, chords: { inst: "pad", beats: [0], len: 3.8, vel: 0.05 }, lead: { inst: "pluck", density: 0.55, octave: 12, steps: 8 }, drums: { taiko: [0, 2.5, 3] } },
  ukiyoe: { prog: CH.japan, scale: SCALES.miyako, bass: { inst: "bass", beats: [0, 1.5, 2], octave: -24 }, chords: { inst: "pluck", beats: [0, 1, 2, 3], len: 0.3 }, lead: { inst: "flute", density: 0.35, octave: 12, steps: 4, len: 0.9, vel: 0.08 }, drums: { taiko: [0, 0.75, 1.5, 2, 3, 3.5], snare: [3] } },
  feature: { prog: CH.feature, scale: SCALES.major, bass: { inst: "bass", beats: [0, 2], octave: -24 }, chords: { inst: "pad", beats: [0], len: 3.9, vel: 0.08 }, lead: { inst: "flute", density: 0.5, octave: 12, steps: 4, len: 0.95, vel: 0.1 }, drums: { taiko: [0], hat: null } },
  cgi: { prog: CH.pop, scale: SCALES.major, bass: { inst: "upright", beats: [0, 2, 2.5], octave: -24 }, chords: { inst: "pluck", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], len: 0.2 }, lead: { inst: "piano", density: 0.5, octave: 12, steps: 8, vel: 0.13 }, drums: { kick: [0, 2], snare: [1, 3], brush: true } },
  winter: { meter: 3, prog: CH.folkMinor, scale: SCALES.harmMinor, bass: { inst: "bass", beats: [0], octave: -24 }, chords: { inst: "pad", beats: [0], len: 2.8, vel: 0.06 }, lead: { inst: "bell", density: 0.7, octave: 12, steps: 6 }, drums: {} },
  folk: { meter: 2, prog: CH.folkMinor, scale: SCALES.harmMinor, bass: { inst: "bass", beats: [0], octave: -24 }, chords: { inst: "reed", beats: [1], len: 0.4, vel: 0.07 }, lead: { inst: "pluck", density: 0.75, octave: 12, steps: 4, tremolo: true }, drums: {} },
  adventure: { prog: CH.pop, scale: SCALES.major, bass: { inst: "bass", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], octave: -24 }, chords: { inst: "saw", beats: [0, 2], len: 1.6, vel: 0.05 }, lead: { inst: "saw", density: 0.55, octave: 12, steps: 8, vel: 0.07 }, drums: { kick: [0, 1.5, 2], snare: [1, 3], hat: "8" } },
  sparkle: { prog: CH.citypop, scale: SCALES.major, bass: { inst: "tri", beats: [0, 1, 2, 3], octave: -24 }, chords: { inst: "pad", beats: [0], len: 3.8, vel: 0.06 }, lead: { inst: "bell", density: 0.65, octave: 12, steps: 8 }, drums: { kick: [0, 2], snare: [1, 3], hat: "8" } },
  zany: { prog: CH.pop, scale: SCALES.major, bass: { inst: "tri", beats: [0, 1, 2, 3], octave: -24, walk: true }, chords: { inst: "pluck", beats: [1, 3], len: 0.2 }, lead: { inst: "square", density: 0.6, octave: 12, steps: 8, vel: 0.05, duty: 0.25 }, drums: { kick: [0, 2], snare: [1, 3], woodblock: [0.5, 2.5, 3.25] } },
  saturday: { prog: CH.minorEpic, scale: SCALES.minor, bass: { inst: "saw", beats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], octave: -24, vel: 0.08 }, chords: { inst: "saw", beats: [0, 1.5, 3], len: 0.3, vel: 0.05 }, lead: { inst: "square", density: 0.5, octave: 12, steps: 8, vel: 0.05 }, drums: { kick: [0, 2], snare: [1, 3], hat: "8" } },
};

function recipe(R) {
  return (tr, { beat, bars, r, key }) => {
    const meter = R.meter || 4;
    let lastDeg = 7;
    for (let b = 0; b < bars; b++) {
      const t0 = b * meter * beat;
      const chord = R.prog[b % R.prog.length].map((n) => n + 60 + key);
      const next = R.prog[(b + 1) % R.prog.length][0] + 60 + key;
      // bass
      if (R.bass) R.bass.beats.forEach((bt, i) => {
        const n = R.bass.walk ? [chord[0], chord[1], chord[2], next - 1][i % 4] : (i % 2 && chord[2] ? chord[2] : chord[0]);
        play(tr, R.bass.inst, t0 + bt * beat, n + (R.bass.octave ?? -24), beat * 0.9, R.bass.vel ?? 0.35, b * 50 + i);
      });
      // chords (optionally arpeggiated)
      if (R.chords) R.chords.beats.forEach((bt, i) => {
        const notes = R.chords.arp ? [chord[i % chord.length]] : chord;
        notes.forEach((n, k) => play(tr, R.chords.inst, t0 + bt * beat + (R.swing && bt % 1 ? beat * R.swing : 0), n + (R.chords.octave ?? 0), beat * (R.chords.len ?? 0.5), R.chords.vel ?? 0.08, b * 70 + i * 5 + k, R.chords.duty));
      });
      // lead: stepwise walk on the scale, density = chance per step
      const steps = R.lead?.steps ?? 8;
      if (R.lead) for (let s = 0; s < steps; s++) {
        if (r() > R.lead.density) continue;
        lastDeg = Math.max(0, Math.min(13, lastDeg + Math.floor(r() * 5) - 2));
        const sc = R.scale, n = 60 + key + sc[lastDeg % sc.length] + 12 * Math.floor(lastDeg / sc.length) + (R.lead.octave ?? 12) - 12;
        const at = t0 + (s * meter * beat) / steps + (R.swing && s % 2 ? beat * R.swing : 0);
        const len = ((meter * beat) / steps) * (R.lead.len ?? 0.8);
        if (R.lead.tremolo) for (let k = 0; k < 4; k++) play(tr, R.lead.inst, at + k * len / 4, n, len / 4, 0.18, b * 90 + s * 4 + k);
        else play(tr, R.lead.inst, at, n, len, R.lead.vel ?? 0.2, b * 90 + s, R.lead.duty);
      }
      // drums
      const D = R.drums || {};
      (D.kick || []).forEach((bt) => tr.kick(t0 + bt * beat, 0.45));
      (D.snare || []).forEach((bt, i) => (D.brush ? tr.swish(t0 + bt * beat, beat * 0.6, 0.06, b * 9 + i) : tr.snare(t0 + bt * beat, 0.2, b * 9 + i)));
      (D.taiko || []).forEach((bt, i) => tr.taiko(t0 + bt * beat, i === 0 ? 0.6 : 0.4, i === 0 ? 62 : 85));
      (D.woodblock || []).forEach((bt, i) => tr.noise(t0 + bt * beat, 0.05, 0.14, b * 11 + i, 1100));
      if (D.hat) { const n = D.hat === "16" ? 4 : 2; for (let k = 0; k < meter * n; k++) tr.hat(t0 + (k * beat) / n, k % n ? 0.04 : 0.06, b * 100 + k); }
    }
    return R.prog[0];
  };
}

function play(tr, inst, t, n, len, vel, seed, duty) {
  switch (inst) {
    case "piano": return tr.piano(t, n, len, vel);
    case "bass": return tr.bass(t, n, len, vel);
    case "upright": return tr.upright(t, n, len, vel);
    case "vibes": return tr.vibes(t, n, len, vel);
    case "bell": return tr.bell(t, n, vel);
    case "pluck": return tr.pluck(t, n, Math.max(vel, 0.18), seed);
    case "flute": return tr.flute(t, n, len, vel, seed);
    case "square": return tr.square(t, n, len, vel, duty ?? 0.5);
    case "tri": return tr.tri(t, n, len, vel);
    case "saw": return tr.saw(t, n, len, vel);
    case "epiano": return tr.epiano(t, n, len, vel);
    case "pad": return tr.pad(t, n, len, vel);
    case "reed": return tr.reed(t, n, len, vel);
    default: return tr.piano(t, n, len, vel);
  }
}

const GENRES = { ragtime, lofi, cooljazz, waltz, pentatonic };
for (const [k, R] of Object.entries(RECIPES)) GENRES[k] = recipe(R);
const METER = { waltz: 3, ...Object.fromEntries(Object.entries(RECIPES).filter(([, R]) => R.meter).map(([k, R]) => [k, R.meter])) };

export const genres = Object.keys(GENRES);

export function compose({ genre = "ragtime", bpm = 120, seconds = 10, seed = 7, key = 0 }) {
  const fn = GENRES[genre] || ragtime;
  const tr = new Track(seconds + 2);
  const beat = 60 / bpm;
  const meter = METER[genre] || 4;
  const bars = Math.ceil(seconds / (beat * meter)) + 1;
  const final = fn(tr, { beat, bars, r: rng(seed), key });
  // end on the tonic chord
  const end = seconds - beat * 2;
  const plucky = ["pentatonic", "eerie", "nihonga", "ukiyoe", "folk", "polka"].includes(genre);
  if (end > 0) final.forEach((n) => (plucky ? tr.pluck(end, 60 + key + n, 0.2, 99 + n) : genre === "chiptune" ? tr.square(end, 60 + key + n, beat * 2, 0.04) : tr.piano(end, 60 + key + n, beat * 2, 0.1)));
  return tr.buf.subarray(0, Math.ceil(seconds * SR));
}
